const displayPlayers=players=>[...players].sort((a,b)=>{const genderOrder={F:0,M:1,X:2,'':3},group=(genderOrder[a.gender]??3)-(genderOrder[b.gender]??3);if(group)return group;const av=playerDisplaySort==='number'?String(a.number||'').padStart(10,'0'):a.name,bv=playerDisplaySort==='number'?String(b.number||'').padStart(10,'0'):b.name;return av.localeCompare(bv,undefined,{numeric:true,sensitivity:'base'})||a.name.localeCompare(b.name);});
const pairedDefenderOrder=(offense,defenders,pairings=[])=>{const remaining=new Set(defenders),ordered=[];for(const receiverId of offense){const pairing=pairings.find(pair=>pair.includes(receiverId)&&pair.some(id=>id!==receiverId&&remaining.has(id))),defenderId=pairing?.find(id=>id!==receiverId&&remaining.has(id));if(defenderId){ordered.push(defenderId);remaining.delete(defenderId);}}return [...ordered,...defenders.filter(id=>remaining.has(id))];};
const rememberPairing=(pairings,receiverId,defenderId)=>{if(!receiverId||!defenderId||receiverId===defenderId)return;const existing=pairings.find(pair=>pair.includes(receiverId)&&pair.includes(defenderId));if(!existing)pairings.push([receiverId,defenderId]);};
